CREATE TYPE "MovementType" AS ENUM ('income', 'expense');
CREATE TYPE "ExpenseNature" AS ENUM ('fixed', 'variable');
CREATE TYPE "Recurrence" AS ENUM ('none', 'weekly', 'biweekly', 'monthly', 'yearly');
CREATE TABLE "User" ("id" UUID NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RefreshSession" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RefreshSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "name" VARCHAR(60) NOT NULL, "slug" VARCHAR(70) NOT NULL, "isDefault" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Movement" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "categoryId" UUID NOT NULL, "amount" INTEGER NOT NULL, "date" DATE NOT NULL, "description" VARCHAR(80) NOT NULL, "notes" VARCHAR(240), "type" "MovementType" NOT NULL, "expenseNature" "ExpenseNature" NOT NULL DEFAULT 'variable', "recurrence" "Recurrence" NOT NULL DEFAULT 'none', "recurrenceSourceId" UUID, "recurrenceEnd" DATE, "recurrencePaused" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Movement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Budget" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "month" CHAR(7) NOT NULL, "general" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Budget_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CategoryBudget" ("id" UUID NOT NULL, "budgetId" UUID NOT NULL, "categoryId" UUID NOT NULL, "amount" INTEGER NOT NULL, CONSTRAINT "CategoryBudget_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SavingsGoal" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "name" VARCHAR(80) NOT NULL, "targetAmount" INTEGER NOT NULL, "targetDate" DATE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SavingsGoal_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SavingsContribution" ("id" UUID NOT NULL, "goalId" UUID NOT NULL, "amount" INTEGER NOT NULL, "date" DATE NOT NULL, CONSTRAINT "SavingsContribution_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE INDEX "RefreshSession_userId_expiresAt_idx" ON "RefreshSession"("userId", "expiresAt");
CREATE INDEX "Category_userId_name_idx" ON "Category"("userId", "name");
CREATE UNIQUE INDEX "Category_userId_slug_key" ON "Category"("userId", "slug");
CREATE INDEX "Movement_userId_date_idx" ON "Movement"("userId", "date" DESC);
CREATE INDEX "Movement_userId_type_date_idx" ON "Movement"("userId", "type", "date");
CREATE INDEX "Movement_userId_categoryId_date_idx" ON "Movement"("userId", "categoryId", "date");
CREATE INDEX "Movement_userId_amount_idx" ON "Movement"("userId", "amount");
CREATE INDEX "Budget_userId_month_idx" ON "Budget"("userId", "month");
CREATE UNIQUE INDEX "Budget_userId_month_key" ON "Budget"("userId", "month");
CREATE INDEX "CategoryBudget_categoryId_idx" ON "CategoryBudget"("categoryId");
CREATE UNIQUE INDEX "CategoryBudget_budgetId_categoryId_key" ON "CategoryBudget"("budgetId", "categoryId");
CREATE INDEX "SavingsGoal_userId_idx" ON "SavingsGoal"("userId");
CREATE INDEX "SavingsContribution_goalId_date_idx" ON "SavingsContribution"("goalId", "date");
ALTER TABLE "RefreshSession" ADD CONSTRAINT "RefreshSession_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Category" ADD CONSTRAINT "Category_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Movement" ADD CONSTRAINT "Movement_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Movement" ADD CONSTRAINT "Movement_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Budget" ADD CONSTRAINT "Budget_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CategoryBudget" ADD CONSTRAINT "CategoryBudget_budgetId_fkey" FOREIGN KEY ("budgetId") REFERENCES "Budget"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CategoryBudget" ADD CONSTRAINT "CategoryBudget_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SavingsGoal" ADD CONSTRAINT "SavingsGoal_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SavingsContribution" ADD CONSTRAINT "SavingsContribution_goalId_fkey" FOREIGN KEY ("goalId") REFERENCES "SavingsGoal"("id") ON DELETE CASCADE ON UPDATE CASCADE;
